function LPL.EraTalentCatalog:GetTabsForClass(classID)
  classID = tonumber(classID)
  local ids = classID and self.classTabs[classID]
  if not ids then return {} end
  local out = {}
  for i = 1, #ids do
    out[i] = self.tabs[ids[i]]
  end
  return out
end

function LPL.EraTalentCatalog:GetTalentsForTab(tabID)
  tabID = tonumber(tabID)
  local out = {}
  if not tabID then return out end
  for _, talent in pairs(self.talents) do
    if talent.tabID == tabID then
      out[#out + 1] = talent
    end
  end
  table.sort(out, function(a, b)
    if a.tier ~= b.tier then return a.tier < b.tier end
    return a.column < b.column
  end)
  return out
end
